/** BlobStore over R2 (the `ASSETS` bucket) — generic put/get/delete for opaque
 *  blobs (backup bundles). Keys are server-generated by the caller. */
import type { BlobStore } from '../backups/types.js';

export function createBlobStore(bucket: R2Bucket): BlobStore {
  return {
    async put(key, body, contentType) {
      await bucket.put(key, body as ArrayBuffer, { httpMetadata: { contentType } });
    },
    async get(key) {
      const obj = await bucket.get(key);
      return obj ? await obj.arrayBuffer() : null;
    },
    async delete(keys) {
      if (keys.length) await bucket.delete(keys);
    },
  };
}
